// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(address actor, uint256 amount, bool shouldFail) public {
        vm.assume(actor != address(0));
        Token t = new Token();
        t.setShouldFail(shouldFail);
        vm.prank(actor);
        bool ok;
        try c.transfer(actor, address(t), _one(actor), _one(amount)) { ok = true; } catch { ok = false; }
        // Rule: if the token's transferFrom reverts, transfer must revert too.
        assertTrue(!shouldFail || !ok, "transfer succeeded despite failing transferFrom");
    }

    function _one(address a) internal pure returns (address[] memory arr) {
        arr = new address[](1);
        arr[0] = a;
    }

    function _one(uint256 v) internal pure returns (uint256[] memory arr) {
        arr = new uint256[](1);
        arr[0] = v;
    }
}

contract Token {
    bool public shouldFail;

    function setShouldFail(bool b) public { shouldFail = b; }

    function transferFrom(address, address, uint256) public returns (bool) {
        if (shouldFail) revert();
        return true;
    }
}
